// TODO: this needs its own file
//////////// cssos timers //////////////

typedef void VOIDFUNC(void);

struct cssos_timer
{
  struct cssos_timer *next;
  unsigned running; // pad to 16 bytes
  unsigned delta;
  VOIDFUNC *func;
};

#define RT_SECOND 100
#define RT_MILLI(x) (((x)*RT_SECOND + 999)/1000)
void cssos_timer_rewind(struct cssos_timer *t,unsigned ticks);
struct cssos_timer *cssos_timer_create(VOIDFUNC *handler);


